contract InvMutTest {
    C public c;

    constructor(C _c) { c = _c; }

    // drive the contract: supply initial balance to this test contract if needed via payable sender externally
    // single public test function: takes deposit amount and sender address (msg.sender of this call is tester harness),
    // but we cannot change msg.sender when calling c, so we will use this contract as caller; caller's address is address(this).
    // We must ensure this contract has enough ETH to forward the deposit value.
    function runTest(uint depositAmt) public {
        // precondition: target the case depositAmt == MinDeposit
        require(depositAmt > 0);

        uint min = c.MinDeposit();
        require(depositAmt == min);

        // record balance before
        uint before = c.balances(address(this));

        // ensure this contract has enough ETH to send depositAmt
        require(address(this).balance >= depositAmt);

        // perform the deposit call that differs between P and M
        // state-changing call must be top-level
        c.Deposit{value: depositAmt}();

        // observe after
        uint after = c.balances(address(this));

        // ASSERT: on original P deposits equal to MinDeposit are ignored, so balance must be unchanged
        assert(after == before);
    }

    // Allow funding this test contract externally so it can forward ETH to c
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Calls deposit twice: first with some positive value to create a baseline,
    // then with a zero value; asserts that the balance after the zero-deposit
    // equals the balance before it (i.e., zero-value Deposit does not change balance).
    function runTest(uint firstAmt) public payable {
        // require we have enough ether in this contract to forward firstAmt
        require(address(this).balance >= firstAmt, "insufficient balance for test");
        // require firstAmt is at least the contract's MinDeposit so the first deposit is accepted by P
        uint min = c.MinDeposit();
        require(firstAmt >= min, "firstAmt must be >= MinDeposit");

        // First, perform a valid deposit to ensure balances[msg.sender] > 0 baseline
        c.Deposit{value: firstAmt}();

        // Read balance after first deposit
        uint balAfterFirst = c.balances(address(this));

        // Now perform Deposit with zero value
        c.Deposit{value: 0}();

        // Read balance after zero deposit
        uint balAfterZero = c.balances(address(this));

        // Property: zero-value Deposit must not increase the recorded balance
        assert(balAfterZero == balAfterFirst);
    }

    // Allow this test contract to receive ETH so it can forward deposits
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // amount is the Ether sent to c.Deposit; minDepositQuery lets us read c.MinDeposit()
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        uint before = c.balances(address(this));
        uint minDep = c.MinDeposit();

        // call Deposit sending `amount` wei
        c.Deposit{value: amount}();

        uint after = c.balances(address(this));

        // If amount is <= MinDeposit, balance must not increase
        assert(!(amount <= minDep) || after <= before);
    }

    receive() external payable {}
}

