pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address actor, uint256 amount) public {
        // keep actor non-zero and amount wide; MinDeposit is 1 ether in the contract
        vm.assume(actor != address(0));
        // amount must be > 0 to allow binding; we'll let fuzz explore large values including > 1 ether
        vm.assume(amount > 0);

        // Ensure actor has the funds to send
        vm.deal(actor, amount);

        // Record balance before deposit via public getter
        uint256 before = c.balances(actor);

        // Make the call as the actor sending `amount` wei to Deposit
        bool ok;
        vm.prank(actor);
        try c.Deposit{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call, the correct contract (reference) guarantees that if the deposit was accepted
        // (i.e., amount > MinDeposit) then balances[actor] == before + amount without overflow.
        // We express that as: if the call succeeded and amount > MinDeposit then balances == before + amount.
        // This is a universal property the reference satisfies; the mutant without the overflow check
        // can overflow and break this equality for some fuzzed inputs.

        if (ok && amount > 1 ether) {
            // Single assertion required that reads c's public surface
            assertTrue(c.balances(actor) == before + amount);
        } else {
            // If the call didn't succeed or didn't meet MinDeposit, the reference imposes no change;
            // still assert that the stored balance equals before (reference behavior) — this also holds
            // for the reference contract for all inputs.
            assertTrue(c.balances(actor) == before);
        }
    }
}

