import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // General rule: For any actor and deposit amount > MinDeposit such that the addition does not overflow
    // (i.e., msg.value <= type(uint).max - balances_before), the reference contract increases balances[actor]
    // by exactly msg.value. The mutant that removed the overflow check can overflow and thus violate this.
    function testFuzz_property(address actor, uint256 amt) public {
        // keep actor non-zero
        vm.assume(actor != address(0));
        // Actor must have some ETH to send
        uint256 deposit = bound(amt, 0, type(uint256).max);

        // Ensure msg.value > MinDeposit so Deposit's body executes; MinDeposit == 1 ether in C
        vm.assume(deposit > 1 ether);

        // set actor balance enough for the call
        vm.deal(actor, deposit);

        // read prior balance in contract mapping
        uint256 before = c.balances(actor);

        // Constrain to admissible domain where reference must hold: no overflow on addition
        // i.e., before + deposit must not overflow
        vm.assume(deposit <= type(uint256).max - before);

        // Perform the deposit as actor
        vm.prank(actor);
        c.Deposit{value: deposit}();

        uint256 after = c.balances(actor);

        // Single assertion: in the reference, when addition cannot overflow, balances[actor] increases by exactly deposit
        assertTrue(after == before + deposit);
    }
}

