pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: depositor (actor) and amount to deposit
    function testFuzz_property(address depositor, uint256 amount) public {
        // Keep amount wide but meaningful: require greater than MinDeposit (1 ether) so Deposit's body executes
        uint256 min = 1 ether;
        vm.assume(amount > min && amount < 1e30);
        // Make sure depositor has funds
        vm.deal(depositor, amount);

        // Call Deposit as depositor, forwarding Ether
        bool ok;
        vm.prank(depositor);
        try c.Deposit{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property (single assertion): If Deposit returned normally (ok==true), then balances[depositor]
        // must equal amount (since it started at 0 and should be increased by exactly msg.value on success).
        // This holds for the reference implementation for all inputs; the mutant that logs before state update can
        // cause a revert/behavior that makes balances differ for some inputs (the fuzzer will find such).
        if (ok) {
            assertTrue(c.balances(depositor) == amount);
        } else {
            // If the call reverted, the reference still maintains balances==0; assert that as well (observational)
            assertTrue(c.balances(depositor) == 0);
        }
    }
}

